import test from "node:test";
import assert from "node:assert/strict";
import { FixtureMaintenanceGate } from "../scripts/fixture-maintenance-gate.mjs";

// These observations are deliberately generated by a DISPOSABLE test fixture.
// An actual Reach /api/reach/restart-impact currently reports atomicSnapshot:false.
const idle = () => ({
  atomicSnapshot: true, idleConfirmed: true, activeMcpRequests: 0,
  backgroundReconciliationActive: false, jobInspectionAvailable: true,
  browserInspectionAvailable: true, managedBrowser: false,
  managedProcesses: [], durableJobs: [],
});
const run = (gate, observed = idle()) => gate.runExclusive(async () => observed, async () => "fixture-ok");

test("requires a maintenance lease and rejects missing observations", async () => {
  const gate = new FixtureMaintenanceGate();
  await assert.rejects(gate.runExclusive(undefined, async () => {}), /requires inspection/);
  await assert.rejects(gate.runExclusive(async () => undefined, async () => {}), /idle unverified/);
  assert.deepEqual(gate.state, { admissionsClosed: false, inFlight: 0 });
});

test("never treats the live read-only restart-impact report as an exclusive idle gate", async () => {
  const gate = new FixtureMaintenanceGate();
  let switched = 0;
  const report = { ...idle(), atomicSnapshot: false, idleConfirmed: false };
  await assert.rejects(gate.runExclusive(async () => report, async () => { switched++; }), /idle unverified/);
  assert.equal(switched, 0);
  assert.equal(gate.state.admissionsClosed, false);
});

test("rejects unknown, active and incomplete observations fail-closed", async () => {
  const cases = [
    { activeMcpRequests: 1 }, { backgroundReconciliationActive: true },
    { jobInspectionAvailable: false }, { browserInspectionAvailable: false },
    { managedBrowser: null }, { managedBrowser: true },
    { managedProcesses: [{ pid: 42 }] }, { durableJobs: [{ id: "unclaimed", runId: null }] },
    { idleConfirmed: false }, { atomicSnapshot: false },
    { managedProcesses: null }, { durableJobs: undefined },
  ];
  for (const change of cases) {
    const gate = new FixtureMaintenanceGate();
    await assert.rejects(run(gate, { ...idle(), ...change }), /idle unverified/,
      JSON.stringify(change));
    assert.deepEqual(gate.state, { admissionsClosed: false, inFlight: 0 });
  }
});

test("blocks a new task while a pending observation is in progress, then releases admission", async () => {
  const gate = new FixtureMaintenanceGate();
  let finishInspection;
  const pending = new Promise(resolve => { finishInspection = resolve; });
  let activeDuringSwitch = false;
  const maintenance = gate.runExclusive(() => pending, async () => {
    assert.deepEqual(gate.state, { admissionsClosed: true, inFlight: 0 });
    activeDuringSwitch = true;
    assert.throws(() => gate.enterWork(), /admission closed/);
    await assert.rejects(run(gate), /lease already held/);
    return "fixture-ok";
  });
  assert.throws(() => gate.enterWork(), /admission closed/);
  assert.deepEqual(gate.state, { admissionsClosed: true, inFlight: 0 });
  finishInspection(idle());
  assert.equal(await maintenance, "fixture-ok");
  assert.equal(activeDuringSwitch, true);
  const release = gate.enterWork();
  release(); release();
  assert.deepEqual(gate.state, { admissionsClosed: false, inFlight: 0 });
});

test("in-flight work refuses maintenance without interrupting that work", async () => {
  const gate = new FixtureMaintenanceGate();
  const done = gate.enterWork();
  let inspected = false;
  await assert.rejects(gate.runExclusive(async () => {
    inspected = true; return idle();
  }, async () => {}), /active work/);
  assert.equal(inspected, false);
  assert.equal(gate.state.inFlight, 1);
  done();
  assert.equal(await run(gate), "fixture-ok");
});

test("inspection failure and action error reopen admissions", async () => {
  const gate = new FixtureMaintenanceGate();
  await assert.rejects(gate.runExclusive(async () => { throw Error("secret backend error"); },
    async () => {}), /idle unverified/);
  assert.deepEqual(gate.state, { admissionsClosed: false, inFlight: 0 });
  await assert.rejects(gate.runExclusive(async () => idle(),
    async () => { throw Error("fixture switch failed"); }), /fixture switch failed/);
  assert.equal(await run(gate), "fixture-ok");
});


test("a stalled observation times out, restores admission, and cannot activate late", async () => {
  const gate = new FixtureMaintenanceGate();
  let finishInspection;
  const neverSettled = new Promise(resolve => { finishInspection = resolve; });
  let switched = false;
  await assert.rejects(gate.runExclusive(() => neverSettled,
    async () => { switched = true; }, 40), /idle unverified/);
  assert.equal(switched, false);
  assert.deepEqual(gate.state, { admissionsClosed: false, inFlight: 0 });
  finishInspection(idle());
  await Promise.resolve();
  assert.equal(switched, false);
  assert.equal(await run(gate), "fixture-ok");
});

test("rejects invalid observation deadlines before closing admissions", async () => {
  const gate = new FixtureMaintenanceGate();
  for (const deadline of [0, Infinity, -1, 10_001]) {
    await assert.rejects(gate.runExclusive(async () => idle(), async () => {}, deadline),
      /observation deadline/);
    assert.deepEqual(gate.state, { admissionsClosed: false, inFlight: 0 });
  }
});
